// === 配置 ===
const ALLOWED_USERS = [493325033];
const METAPI = 'https://metapi-krj9.onrender.com';

// 选中状态存这里（工作流级别，进程内存；重启后清空，这是有意的：
// 一个聊天里残留的勾选比重新点一次更糟）
const store = $getWorkflowStaticData('global');
if (!store.selection) store.selection = {};

const ev = $input.first().json;
const cb = ev.callback_query;

// ==================== 分支 A：按钮点击 ====================
if (cb) {
  const chatId = cb.message?.chat?.id;
  const userId = Number(cb.from?.id || 0);
  const messageId = cb.message?.message_id;
  const data = String(cb.data || '');

  if (!ALLOWED_USERS.includes(userId)) {
    return [{ json: { action: 'answer', callbackQueryId: cb.id, text: '❌ 未授权', chatId } }];
  }

  const key = String(chatId);
  const selected = store.selection[key] || [];
  let ids = selected.slice();

  // t:<id> 切换选中；go 开始探测；clr 清空；noop 是只有标题的按钮，点它什么都不做
  if (data === 'noop') {
    return [{ json: { action: 'answer', callbackQueryId: cb.id, text: '↑ 点具体站点来勾选', chatId } }];
  }

  if (data === 'clr') {
    ids = [];
    store.selection[key] = ids;
    return [{ json: { action: 'render', callbackQueryId: cb.id, chatId, messageId, selectedIds: ids, notice: '已清空选择' } }];
  }

  if (data === 'go') {
    if (ids.length === 0) {
      return [{ json: { action: 'answer', callbackQueryId: cb.id, text: '⚠️ 请先勾选至少一个站点', chatId } }];
    }
    return [{ json: { action: 'probe', callbackQueryId: cb.id, chatId, messageId, siteIds: ids, selectedIds: ids } }];
  }

  if (data.startsWith('t:')) {
    const id = Number(data.slice(2));
    if (!Number.isInteger(id) || id <= 0) {
      return [{ json: { action: 'answer', callbackQueryId: cb.id, text: '无效站点', chatId } }];
    }
    ids = ids.includes(id) ? ids.filter((x) => x !== id) : ids.concat(id);
    store.selection[key] = ids;
    return [{ json: { action: 'render', callbackQueryId: cb.id, chatId, messageId, selectedIds: ids } }];
  }

  return [{ json: { action: 'answer', callbackQueryId: cb.id, text: '未知操作', chatId } }];
}

// ==================== 分支 B：文字命令 ====================
const msg = ev.message || {};
const chatId = msg.chat?.id;
const userId = Number(msg.from?.id || 0);
const text = (msg.text || '').trim();
const parts = text.split(/\s+/);
const cmd = (parts[0] || '').replace(/^\//, '').toLowerCase();
const args = parts.slice(1).join(' ');

const reply = (t) => [{ json: { action: 'send', chatId, text: t } }];

if (!ALLOWED_USERS.includes(userId)) {
  return reply('❌ 未授权访问\n\n此机器人仅供管理员使用。\n您的 User ID: ' + userId);
}

if (!cmd || cmd === 'help' || cmd === 'start') {
  return reply('🤖 MetAPI 探测机器人\n\n/targets - 选择要探测的站点（按钮勾选）\n/probe all - 探测所有站点\n/probe 180001,180002 - 探测指定站点\n/status - 查看最近一次探测结果\n/help - 显示帮助\n\n⚠️ 探测会消耗真实配额');
}

if (cmd === 'targets') {
  const ids = store.selection[String(chatId)] || [];
  return [{ json: { action: 'render', chatId, messageId: null, selectedIds: ids, notice: '点站点勾选/取消，然后点「开始探测」' } }];
}

if (cmd === 'probe') {
  const raw = args.trim().toLowerCase();
  const siteIds = raw === 'all' || raw === '' ? 'all' : raw.split(/[^0-9]+/).filter(Boolean).map(Number).filter((n) => Number.isInteger(n) && n > 0);
  if (Array.isArray(siteIds) && siteIds.length === 0) {
    return reply('❌ 站点ID格式不对\n\n用法: /probe all 或 /probe 180001,180002');
  }
  return [{ json: { action: 'probe', chatId, messageId: null, siteIds, selectedIds: null } }];
}

if (cmd === 'status') {
  // 不带参数 = 查最近一次；带参数 = 查指定任务
  const url = args.trim() ? METAPI + '/api/remote-probe/status/' + encodeURIComponent(args.trim()) : METAPI + '/api/remote-probe/status';
  return [{ json: { action: 'api', chatId, cmd: 'status', method: 'GET', url, body: null } }];
}

return reply('❓ 未知命令: /' + cmd + '\n\n发送 /help 查看可用命令');

// 拉站点列表 + 当前选中状态，拼成 inline keyboard
const ctx = $('预处理').first().json;
const data = $input.first().json || {};

const chatId = ctx.chatId;
const messageId = ctx.messageId || null;
const selected = (ctx.selectedIds || []).slice();

if (data.error || data.success === false) {
  return [{ json: { chatId, messageId, callbackQueryId: ctx.callbackQueryId || null, text: '❌ 获取站点失败: ' + (data.error?.description || data.message || '未知错误'), replyMarkup: null } }];
}

const sites = data.sites || [];
if (!sites.length) {
  return [{ json: { chatId, messageId, callbackQueryId: ctx.callbackQueryId || null, text: '⚠️ 没有可用站点', replyMarkup: null } }];
}

// Telegram 按钮文字上限很宽，但一行两个更好点。
// data 限 64 字节，所以站点ID用 t:<id>，标题按钮用 noop。
const buttons = [];
for (let i = 0; i < sites.length; i += 2) {
  const row = [];
  for (const s of sites.slice(i, i + 2)) {
    const on = selected.includes(s.siteId);
    // 勾选标记放在文字里，因为 Telegram 按钮不支持真正的勾选框
    row.push({ text: (on ? '✅ ' : '▫️ ') + s.siteName + ' (' + s.modelCount + ')', callback_data: 't:' + s.siteId });
  }
  buttons.push(row);
}

const totalModels = sites.reduce((sum, s) => sum + (s.modelCount || 0), 0);
const selectedModels = sites.filter((s) => selected.includes(s.siteId)).reduce((sum, s) => sum + (s.modelCount || 0), 0);

let text = (ctx.notice ? ctx.notice + '\n\n' : '') + '📋 共 ' + sites.length + ' 个站点 / ' + totalModels + ' 个模型\n';
if (selected.length) {
  text += '已选 ' + selected.length + ' 个站点（约 ' + selectedModels + ' 个模型）\n';
}

buttons.push([
  { text: '🚀 开始探测 (' + selected.length + ')', callback_data: 'go' },
  { text: '🧹 清空', callback_data: 'clr' }
]);

return [{ json: { chatId, messageId, callbackQueryId: ctx.callbackQueryId || null, text, replyMarkup: { inline_keyboard: buttons } } }];

// /probe 或 点了「开始探测」：先看有没有在跑，避免重复计费
const ctx = $('预处理').first().json;

let siteIds;
if (ctx.siteIds === 'all') {
  siteIds = 'all';
} else if (Array.isArray(ctx.siteIds)) {
  siteIds = ctx.siteIds;
} else {
  siteIds = 'all';
}

return [{ json: { chatId: ctx.chatId, messageId: ctx.messageId || null, callbackQueryId: ctx.callbackQueryId || null, siteIds, method: 'GET', url: 'https://metapi-krj9.onrender.com/api/remote-probe/active', body: null, stage: 'check' } }];

// 检查 /active 的返回：在跑就劝退，没跑就真的发起探测
const ctx = $('探测前置检查').first().json;
const data = $input.first().json || {};

if (data.error || data.success === false) {
  return [{ json: { chatId: ctx.chatId, messageId: ctx.messageId, callbackQueryId: ctx.callbackQueryId, method: 'POST', url: 'https://metapi-krj9.onrender.com/api/remote-probe/run', body: { siteIds: ctx.siteIds, waitForCompletion: false, timeout: 300000 }, stage: 'run' } }];
}

if (data.running) {
  // 已经有一次扫描在跑。后台任务会拒绝并发（同一范围复用旧任务），
  // 所以这里直接返回运行中，不要让用户以为新的一次开始了。
  return [{ json: { chatId: ctx.chatId, messageId: ctx.messageId, callbackQueryId: ctx.callbackQueryId, stage: 'busy', text: '⏳ 已有一次探测在进行中\n\n用 /status 查看进度' } }];
}

return [{ json: { chatId: ctx.chatId, messageId: ctx.messageId, callbackQueryId: ctx.callbackQueryId, method: 'POST', url: 'https://metapi-krj9.onrender.com/api/remote-probe/run', body: { siteIds: ctx.siteIds, waitForCompletion: false, timeout: 300000 }, stage: 'run' } }];

// 统一收尾：探测结果 / 状态查询 / 忙碌提示都在这里成文
const start = $('预处理').first().json;
const chatId = start.chatId;
const messageId = start.messageId || null;
const callbackQueryId = start.callbackQueryId || null;

// 上游节点可能是 探测前置检查/决定是否探测/发起探测 之一，逐个找
let payload = null;
for (const name of ['发起探测', '决定是否探测', '探测前置检查']) {
  try {
    const item = $(name).first();
    if (item) { payload = item.json; break; }
  } catch (e) { /* 该分支没走到 */ }
}
payload = payload || {};

const TELEGRAM_LIMIT = 3800;
const out = (text) => {
  const chunks = [];
  let rest = text;
  while (rest.length > TELEGRAM_LIMIT) {
    let cut = rest.lastIndexOf('\n', TELEGRAM_LIMIT);
    if (cut < TELEGRAM_LIMIT / 2) cut = TELEGRAM_LIMIT;
    chunks.push(rest.slice(0, cut));
    rest = rest.slice(cut);
  }
  chunks.push(rest);
  return chunks.map((chunk) => ({ json: { chatId, messageId, callbackQueryId, text: chunk, replyMarkup: null } }));
};

// 忙碌分支
if (payload.stage === 'busy') {
  return out(payload.text || '⏳ 已有探测在进行中');
}

// 探测刚发起
if (payload.status === 'running' || payload.status === 'pending') {
  return out('🚀 探测已启动\n\nTask ID: ' + payload.taskId + '\n\n有两种看法：\n• /status — 最近一次结果\n• /status ' + payload.taskId + ' — 指定任务');
}

if (payload.status === 'completed') {
  return out(formatCompleted(payload));
}

// 状态查询返回
if (payload.success === true && payload.summary) {
  return out(formatCompleted(payload));
}

if (payload.error || payload.success === false) {
  return out('❌ 失败: ' + (payload.error?.description || payload.message || '未知错误'));
}

return out('❓ 没有拿到结果: ' + JSON.stringify(payload).slice(0, 300));

function formatCompleted(data) {
  const sm = data.summary || {};
  let text = '✅ 探测完成' + (data.taskId ? '（' + String(data.taskId).slice(0, 8) + '）' : '') + '\n\n';
  text += '总计 ' + (sm.totalProbed ?? 0) + '｜可用 ' + (sm.supported ?? 0) + '｜不可用 ' + (sm.unsupported ?? 0) + '｜不确定 ' + (sm.inconclusive ?? 0) + '\n';
  if (sm.durationMs) text += '耗时 ' + (sm.durationMs / 1000).toFixed(1) + 's\n';
  const av = data.available || [];
  if (!av.length) return text + '\n⚠️ 没有可用模型';
  text += '\n🟢 可用模型 ' + av.length + ' 个（按站点排序）:\n';
  // 服务端已按 站点→模型 排好，这里不再重排，只按站点分组换行
  let lastSite = null;
  av.forEach((m) => {
    if (m.siteName !== lastSite) {
      text += '\n【' + m.siteName + '】\n';
      lastSite = m.siteName;
    }
    text += '  ' + m.modelName + (m.latencyMs ? ' · ' + m.latencyMs + 'ms' : '') + (m.balance !== null && m.balance !== undefined ? ' · $' + m.balance : '') + '\n';
  });
  return text;
}

// 把 answer 分支的文案准备好（Telegram 的 answerCallbackQuery 只接受短文本）
const ctx = $('预处理').first().json;
return [{ json: { callbackQueryId: ctx.callbackQueryId || '', answerText: ctx.text || '' } }];
